const reset = () => {
  data.value = Object.assign({}, defaultData.value);
};

const onClickBody = (id: string) => {
  if (data.value[id]) {
    if (data.value[id] == 3) {
      data.value[id] = null;
    } else {
      data.value[id]++;
    }
  } else {
    data.value[id] = 1;
  }
};
const getFillBody = (id: string) => {
  if (data.value[id] == 1) {
    return "#F8C852";
  } else if (data.value[id] == 2) {
    return "#E89F29";
  } else if (data.value[id] == 3) {
    return "#E9594C";
  } else {
    return "#FFFFFF";
  }
};

const setFormData = () => {
  if (props.openedData) {
    const deFormatedArray = props.openedData.bodies.reduce(
      (acc: any, item: any) => {
        acc[item.anggotaTubuh] = item.grade;
        return acc;
      },
      {} as Record<string, number | null>
    );
    data.value = Object.assign({}, deFormatedArray);
  } else data.value = Object.assign({}, defaultData.value);
};

onBeforeMount(() => {
  setFormData();
});

// NOTE Untuk merefresh form yang sedang dibuka jika ada perubahan data
const storedRMData = computed(() => rekamMedisStore.openedRekamMedis);
watch(storedRMData, (newRM) => {
  setFormData();
});

const submitObject = () => {
  const formatedData = Object.entries(data.value).map(([key, value]) => ({
    grade: value,
    anggotaTubuh: key,
  }));
  return formatedData;
};

defineExpose({
  submitObject,
  reset
});
